"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0961-03-06:0":{"b": ["سقوط قنديّة: نيقفوروس فوكاس يستردّ كريت", "aeefb280"], "d": ["استولت القوات البيزنطية بقيادة نيقفوروس فوكاس على قنديّة في 6 آذار 961 بعد حصار دام سنة؛ وانتهت إمارة كريت التي دامت نحو 130 عامًا. وترك جزء من المسلمين الجزيرة، وأُكره جزء على تغيير دينه.", "ec04c12b"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0962-01-01:0":{"b": ["أحمد بن الحسن الكلبي يستولي بعد حصار دام سبعة أشهر على قلعة طورمينا البيزنطية ويسميها المعزية", "37e8ae59"], "d": ["أحمد بن الحسن الكلبي يستولي بعد حصار دام سبعة أشهر على قلعة طورمينا البيزنطية ويسميها المعزية.", "f8fcc7b1"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0965-01-01:0":{"b": ["نيقفوروس فوكاس يحتل المصيصة وطرسوس (354/965).", "045053b4"], "d": ["نيقفوروس فوكاس يحتل المصيصة وطرسوس (354/965).", "045053b4"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0965-08-16:0":{"b": ["طرسوس تستسلم لبيزنطة: كيليكية تدخل تحت السيادة البيزنطية", "b05e9bd3"], "d": ["استسلمت المصيصة (موبسوستيا) في تموز 965، وطرسوس بعد شهر في 16 آب 965 بشروط إنسانية، وعادت مدينة مسيحية. وبذلك ضُمت منطقة كيليكية إلى بيزنطة.", "faeb461f"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0969-10-28:0":{"b": ["أنطاكية تنتقل إلى يد بيزنطة", "ad0a5da3"], "d": ["بعد أن استولت الجيوش البيزنطية على كثير من القلاع والمدن في شمال سوريا، استولى ميخائيل بورتزيس وبطرس فوكاس القادمان من كيليكية على أنطاكية في 28 تشرين الأول 969. وظلت المدينة نحو 115 عامًا القاعدة الرئيسية لبيزنطة في سوريا.", "38b840e3"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0971-04-13:0":{"b": ["تزيمسكيس يستولي على بريسلاف الكبرى بالهجوم: شرق بلغاريا يُضم إلى بيزنطة", "07c84840"], "d": ["دخل يوانيس تزيمسكيس سهل بريسلاف في 12 نيسان 971؛ وسقطت مساء 13 نيسان العاصمة البلغارية التي دافع عنها رجال سفياتوسلاف. وأُسر القيصر بوريس وامتد الحكم البيزنطي إلى تراقيا وشرق بلغاريا.", "ae050b34"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0979-01-01:0":{"b": ["أذربيجان تنتقل إلى الروادية؛ والمسافريون ينسحبون إلى طارم (979 أو 980)", "b5b0e767"], "d": ["أذربيجان تنتقل إلى الروادية؛ والمسافريون ينسحبون إلى طارم (979 أو 980)", "b5b0e767"]},
