"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0992-01-01:0":{"b": ["هارون بغرا خان يستولي على سمرقند؛ والقراخانيون يدخلون ما وراء النهر لأول مرة", "31e0d0ae"], "d": ["استولى هارون بغرا خان، الذي دعاه أبو علي السيمجوري وفائق الخاصة باتفاق سري، على سمرقند في أوائل 992، ثم زحف على بخارى؛ ومات في قوچقار باشي أثناء عودته إلى كاشغر.", "8377be9f"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0992-05-07:0":{"b": ["القراخاني هارون بغرا خان يستولي على بخارى", "36955b70"], "d": ["استولى هارون بغرا خان، الذي اتفق سرًا مع أبي علي السيمجوري وفائق الخاصة، على بخارى عاصمة السامانيين في ربيع الأول 382 (أيار 992)؛ ومرض ومات بعد قليل.", "cdd97d30"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0992-08-18:0":{"b": ["نوح الثاني يسترد بخارى بمعونة التركمان السلاجقة", "8a88b4d3"], "d": ["في 15 جمادى الآخرة 382 (18 آب 992) استرد نوح الثاني بخارى بمعونة التركمان السلاجقة بعد وفاة هارون بغرا خان.", "00c3767a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0993-01-01:0":{"b": ["زيري بن عطية يهزم والي الفاطميين يدّو بن يعلى ويسترد فاس؛ ويبدأ تأسيس وجدة.", "69e1def0"], "d": ["زيري بن عطية يهزم والي الفاطميين يدّو بن يعلى ويسترد فاس؛ ويبدأ تأسيس وجدة.", "69e1def0"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0997-01-01:0":{"b": ["وفاة فخر الدولة؛ والسلار إبراهيم بن المرزبان يستولي على زنجان وأبهر وسهرورد وطارم (387/997).", "f7dde64a"], "d": ["وفاة فخر الدولة؛ والسلار إبراهيم بن المرزبان يستولي على زنجان وأبهر وسهرورد وطارم (387/997).", "f7dde64a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0998-03-03:0":{"b": ["محمود يهزم أخاه إسماعيل ويعتلي عرش الغزنويين", "b2acf57c"], "d": ["تحرك محمود، وكان في نيسابور، غير معترف بوصية أبيه؛ والتقى جيشا الأخوين في ربيع الأول 388 (آذار 998) فهزم محمود إسماعيل واعتلى عرش الغزنويين.", "3c2c1e3d"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0999-10-14:0":{"b": ["القراخاني إيليك خان نصر يدخل بخارى؛ وأسرة السامانيين تُنفى إلى أوزكند، وتنتهي الدولة فعليًا", "ec519748"], "d": ["احتل القراخانيون بخارى في ذي القعدة 389 (تشرين الأول 999)؛ وأُسر عبد الملك وسيقت أسرة السامانيين إلى أوزكند وسُجنت. وعيّن إيليك خان نصر ولاته في المنطقة.", "ef9a0a65"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1000-01-01:0":{"b": ["الدوج بييترو الثاني أورسيولو يخضع مدن دلماسيا ويصير «دوق دلماسيا»", "fa3dde09"], "d": ["أبحر أورسيولو بأسطول كبير بدعوة من أهل دلماسيا فهزم الكروات والناريتانيين وطهّر الأدرياتيكي من القرصنة، وتلقى الضريبة ويمين الولاء من مدن دلماسيا؛ ونال لقب «دوق دلماسيا». وبايعت زارا الدوج عام 1000.", "d2c778fc"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1000-01-01:1":{"b": ["راغوزا (دوبروفنيك) ومدن جنوب دلماسيا تبايع أورسيولو", "6121e2e9"], "d": ["استقبلت راغوزا، وهي أقصى مدن دلماسيا جنوبًا، جيش الدوج في جزيرة سان ماسيمو بسفرائها ورئيس أساقفتها وقدمت الولاء للبندقية في حملة أورسيولو على دلماسيا.", "638f8cad"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1013-01-01:0":{"b": ["محمود يأخذ لاهور من الهندوشاهيين؛ وتصير لاهور أحب مدن الغزنويين", "37ab3445"], "d": ["انتقلت لاهور، التي كانت بعد 991 في يد الهندوشاهيين، إلى يد محمود الغزنوي في 1013-1014؛ وحصّن محمود قلعة لاهور وأقام حامية من الجنود الأتراك والطاجيك الذين جلبهم من خراسان. ولما فقد الغزنويون استقلالهم (بعد 1157) صارت لاهور مركز الفرع الباقي في الشرق.", "90b6f385"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1015-01-01:0":{"b": ["الملك روبير الثاني يضم دوقية بورغوندي إلى التاج الفرنسي بعد حرب دامت ثلاث عشرة سنة", "257ea2c6"], "d": ["بعد وفاة الدوق هنري في 1002 اندلعت الحرب على دوقية بورغوندي؛ وضم ملك فرنسا روبير الثاني الدوقية إلى المملكة عام 1015 في ختام حرب دامت 13 عامًا رغم مقاومة كونت بورغوندي أوتو-وليم، وأعطاها لابنه هنري (هنري الأول فيما بعد).", "9b353b9c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-01-01:0":{"b": ["باسيليوس الثاني يدخل أوهريد: العاصمة البلغارية الغربية تنتقل إلى بيزنطة", "05fe0972"], "d": ["استسلمت الأسرة البلغارية، التي قاومت أربع سنوات بعد وفاة صموئيل، لباسيليوس الثاني عند أبواب أوهريد في أوائل 1018. وبقيت أسقفية أوهريد الكبرى مركز المسيحية السلافية تحت الحكم البيزنطي.", "b6ac5adb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-01-01:1":{"b": ["ملك بولندا بوليسلاف شروبري يستولي على كييف بدعم ألماني وبيتشينيغي", "3e44ca65"], "d": ["في آب 1018 استولى بوليسلاف على كييف بقوات ألمانية وبيتشينيغية؛ وأجلس على العرش صهره سفياتوبولك، بعد أن هزم ياروسلاف على نهر بوغ. ولم يستطع ياروسلاف استرداد كييف إلا في 1019.", "02428d3c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-05-20:0":{"b": ["محمود يستولي على مدينة ماثورا (موتّرا)", "78547f01"], "d": ["في حملة قنوج استولى الجيش الغزنوي على مدينة ماثورا الواقعة في منتصف طريق دلهي وآغرا (409/1018).", "bb198817"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-12-20:0":{"b": ["محمود يفتح قنوج (كانياكوبجا)", "258b5624"], "d": ["غادر محمود غزنة في 13 جمادى الأولى 409 (27 أيلول 1018) في حملته الهندية الثانية عشرة؛ وبعد قلعة سرساوة وطاعة راجا باران وماثورا فُتحت قنوج، الهدف الأصلي، في 8 شعبان 409 (20 كانون الأول 1018).", "5952deed"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1028-01-01:0":{"b": ["إعلان كنود الكبير ملكًا على النرويج؛ وفرار أولاف هارالدسون", "89688331"], "d": ["جاء كنود إلى النرويج عام 1028 بأسطول من خمسين سفينة وهتف به أوريتينغ ملكًا على النرويج؛ وفرّ الملك أولاف الثاني هارالدسون أولًا إلى السويد ثم إلى روس (غاردريكي).", "35460867"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1030-01-01:0":{"b": ["تأسيس كونتية أفيرسا: راينولف دريغو يصير كونتًا نورمانديًا", "ec99b57a"], "d": ["في عام 1030 أسكن دوق نابولي سرجيوس راينولف في قلعة أفيرسا فنال النورمان لأول مرة قاعدة دائمة وبدأ الفتح المنظم لجنوب إيطاليا.", "8d2a9071"]},
